extends "res://project-pause-runtime.gd"
var probe_physics := false
var probe_port
func _ready() -> void:
	super._ready()
	call_deferred("check_contract")
func _physics_process(delta: float) -> void:
	if probe_physics:
		probe_physics = false
		assert(not probe_port.request_pause(true), "physics callback paused the tree")
		call_deferred("finish_project")
		print("PAUSE_CONTRACT:" + JSON.stringify({"mode":"physics","ok":true}))
		return
	super._physics_process(delta)
func check_contract() -> void:
	await get_tree().process_frame
	var mode := "finish"
	for argument in OS.get_cmdline_user_args():
		if argument.begins_with("--pause-case="):
			mode = argument.trim_prefix("--pause-case=")
	var menu_behavior = current.find_child("behavior_c011ec70_2026_4113_8113_000000000400", true, false)
	var old_port = menu_behavior.get_meta("viento_project_pause")
	assert(menu_behavior.get_meta("viento_project_retry").request_retry("c011ec70-2026-4113-8113-000000000031", {"score":0,"health":3,"door_open":false}))
	flush_requests()
	var behavior = current.find_child("behavior_da9bf4ac_e2ea_4c36_b5fc_678100ff68b0", true, false)
	var port = behavior.get_meta("viento_project_pause")
	var game_port = behavior.get_meta("viento_project")
	assert(not old_port.request_pause(true) and old_port.status() == "unavailable" and not old_port.is_paused())
	assert(not pause_request(RefCounted.new(), true))
	assert(not PausePort.new(self).request_pause(true))
	assert(not port.configure_toggle_action("missing_action"))
	var state := shared_state.duplicate(true)
	var revision := state_revision
	var budget = execution_budget.snapshot()
	var visit := visit_index
	var scene_identity = current.get_instance_id()
	var seconds := total_seconds
	var sequence := pause_sequence
	if mode == "physics":
		probe_port = port
		probe_physics = true
		return
	flushing = true
	assert(not port.request_pause(true))
	flushing = false
	pending_scene = "c011ec70-2026-4113-8113-000000000032"
	assert(not port.request_pause(true) and pending_scene == "c011ec70-2026-4113-8113-000000000032")
	pending_scene = ""
	retry_pending = {"sentinel":true}
	assert(not port.request_pause(true) and retry_pending == {"sentinel":true})
	retry_pending = {}
	for service in [event_bus, audio_control, animation_control]:
		service.queue.push_back({"sentinel":true})
		assert(not port.request_pause(true) and service.queue == [{"sentinel":true}])
		service.queue.clear()
	for property in get_property_list():
		if property["name"] == "animation_completions":
			var completion = get("animation_completions")
			completion.queue.push_back({"sentinel":true})
			assert(not port.request_pause(true) and completion.queue.size() == 1)
			completion.queue.clear()
	assert(pause_phase == "running" and not get_tree().paused and pause_sequence == sequence)
	assert(shared_state == state and state_revision == revision and execution_budget.snapshot() == budget and visit_index == visit and current.get_instance_id() == scene_identity)
	assert(port.request_pause(true) and port.is_paused() and port.status() == "paused" and get_tree().paused)
	sequence = pause_sequence
	assert(port.request_pause(true) and pause_sequence == sequence)
	assert(game_port.read_state("score") == null and not game_port.write_state("paused_write", 1) and not game_port.publish_event("game.paused", true) and not game_port.play_audio("c011ec70-2026-4113-8113-000000000500") and not game_port.request_scene("c011ec70-2026-4113-8113-000000000032"))
	flush_requests()
	await get_tree().create_timer(0.2, true).timeout
	assert(total_seconds == seconds and shared_state == state and state_revision == revision and execution_budget.snapshot() == budget and current.get_instance_id() == scene_identity and visit_index == visit)
	assert(port.request_pause(false) and port.status() == "waiting-for-release" and get_tree().paused)
	assert(port.request_pause(true) and port.status() == "paused" and get_tree().paused)
	print("PAUSE_CONTRACT:" + JSON.stringify({"mode":mode,"ok":true,"visit":visit_index,"state":shared_state,"budget":execution_budget.snapshot(),"phase":pause_phase}))
	if mode == "abort":
		abort_project()
		assert(not get_tree().paused and old_port.status() == "unavailable" and port.status() == "unavailable")
	elif mode == "close":
		_notification(NOTIFICATION_WM_CLOSE_REQUEST)
	else:
		finish_project()
